styles.css.beforeText:
:root{
  --bg:#071018;--surface:#0d1822;--surface2:#111f2b;--line:#223443;--text:#eef5f7;--muted:#91a6b2;
  --accent:#7dd3fc;--accent2:#c4b5fd;--good:#86efac;--warn:#fcd34d;--danger:#fca5a5;
  --shadow:0 18px 48px rgba(0,0,0,.25)
}
*{box-sizing:border-box}html{background:var(--bg);color:var(--text);font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}
body{margin:0;min-height:100vh;background:
  radial-gradient(circle at 15% -10%,rgba(125,211,252,.12),transparent 28rem),
  radial-gradient(circle at 88% 6%,rgba(196,181,253,.10),transparent 24rem),var(--bg)}
button,input,select{font:inherit}.topbar{position:sticky;top:0;z-index:20;display:flex;justify-content:space-between;gap:1rem;align-items:center;padding:14px max(20px,4vw);background:rgba(7,16,24,.86);backdrop-filter:blur(18px);border-bottom:1px solid rgba(255,255,255,.06)}
.brand{display:flex;align-items:center;gap:12px}.brand-mark{width:42px;height:42px;border-radius:13px;display:grid;place-items:center;font-weight:800;color:#071018;background:linear-gradient(135deg,var(--accent),var(--accent2));box-shadow:0 0 40px rgba(125,211,252,.2)}
.brand h1{font-size:18px;margin:0}.brand p{font-size:12px;color:var(--muted);margin:2px 0 0}.header-actions{display:flex;gap:8px}
main{width:min(1540px,94vw);margin:auto;padding:34px 0 80px}.hero{display:grid;grid-template-columns:minmax(0,1.2fr) minmax(340px,.8fr);gap:28px;align-items:end;padding:20px 4px 30px}
.eyebrow{letter-spacing:.14em;font-size:11px;font-weight:800;color:var(--accent);margin:0 0 8px}.hero h2{font-size:clamp(34px,5vw,68px);line-height:.98;letter-spacing:-.045em;margin:0;max-width:900px}.hero-copy{font-size:17px;line-height:1.65;color:var(--muted);max-width:760px;margin:20px 0 0}
.stats{display:grid;grid-template-columns:repeat(2,1fr);gap:10px}.stat{padding:18px;border:1px solid var(--line);border-radius:16px;background:linear-gradient(180deg,rgba(255,255,255,.035),rgba(255,255,255,.01))}.stat strong{display:block;font-size:28px}.stat span{font-size:12px;color:var(--muted)}
.card{background:linear-gradient(180deg,rgba(17,31,43,.96),rgba(11,23,32,.96));border:1px solid var(--line);border-radius:20px;box-shadow:var(--shadow)}
.controls{display:grid;grid-template-columns:2fr repeat(5,1fr);gap:12px;padding:14px}.controls>div{min-width:0}.controls label{display:block;font-size:11px;font-weight:750;color:var(--muted);margin:0 0 6px;text-transform:uppercase;letter-spacing:.06em}.controls input[type=search],.controls select{width:100%;height:42px;border:1px solid #2c4151;background:#09141d;color:var(--text);border-radius:11px;padding:0 12px;outline:none}.controls input:focus,.controls select:focus{border-color:var(--accent)}.switch-row{height:42px;display:flex!important;align-items:center;gap:8px;text-transform:none!important;letter-spacing:0!important}
.tabs{display:flex;gap:7px;padding:18px 0 12px;overflow:auto}.tab,.ghost{border:1px solid var(--line);background:#0b1720;color:var(--muted);border-radius:11px;padding:10px 14px;cursor:pointer}.tab.active,.tab:hover,.ghost:hover{color:var(--text);border-color:#405869;background:#132330}.link-button{text-decoration:none;display:inline-flex;align-items:center}
.view{display:none}.view.active{display:block}.map-layout{display:grid;grid-template-columns:minmax(0,1fr) 360px;gap:14px}.graph-card{min-height:680px;overflow:hidden}.view-head{display:flex;justify-content:space-between;align-items:flex-start;gap:15px;padding:20px 20px 0}.view-head h3,.lineage-grid h3{font-size:20px;margin:0}.legend{display:flex;flex-wrap:wrap;justify-content:flex-end;gap:7px;max-width:520px}.legend-item{display:flex;align-items:center;gap:6px;font-size:10px;color:var(--muted)}.dot{width:8px;height:8px;border-radius:999px}
#network{width:100%;height:590px;display:block}.hint{font-size:11px;color:var(--muted);padding:0 20px 14px;margin:0}.detail-panel{padding:20px;min-height:680px;overflow:auto}.detail-empty{padding-top:25vh;color:var(--muted)}.detail-empty h3{color:var(--text)}
.detail-title{font-size:28px;line-height:1.05;margin:8px 0}.aliases{color:var(--muted);font-size:12px}.badge-row{display:flex;flex-wrap:wrap;gap:6px;margin:13px 0}.badge,.pill{display:inline-flex;align-items:center;border:1px solid #334b5c;background:#0b1720;border-radius:999px;padding:5px 8px;font-size:10px;color:#c5d5dd}.badge.status-established{border-color:#28563a;color:var(--good)}.badge.status-speculative{border-color:#674d1d;color:var(--warn)}.badge.status-interpretation{border-color:#50417c;color:var(--accent2)}
.detail-section{border-top:1px solid var(--line);padding-top:14px;margin-top:15px}.detail-section h4{font-size:11px;text-transform:uppercase;letter-spacing:.08em;color:var(--muted);margin:0 0 8px}.detail-section p{font-size:13px;line-height:1.6;color:#c7d5dc}.tag-list{display:flex;gap:5px;flex-wrap:wrap}.tag{font-size:10px;padding:4px 6px;border-radius:7px;background:#162733;color:#9fc0d0}.relation-list{display:grid;gap:7px}.relation{display:flex;justify-content:space-between;gap:8px;align-items:center;padding:8px 9px;border:1px solid #203542;border-radius:10px;background:#0b1720;cursor:pointer}.relation:hover{border-color:#456378}.relation span{font-size:11px}.relation small{color:var(--muted)}
.timeline{padding:18px 20px 28px}.timeline-era{display:grid;grid-template-columns:120px 1fr;gap:20px;padding:20px 0;border-top:1px solid var(--line)}.timeline-era:first-child{border-top:0}.timeline-era h4{margin:5px 0;color:var(--accent)}.timeline-items{display:grid;grid-template-columns:repeat(auto-fill,minmax(230px,1fr));gap:9px}.timeline-card,.catalog-card,.tree-node{border:1px solid #223845;background:#0b1720;border-radius:13px;padding:12px;cursor:pointer}.timeline-card:hover,.catalog-card:hover,.tree-node:hover{border-color:#45657a}.timeline-card .year{font-size:10px;color:var(--accent)}.timeline-card h5,.catalog-card h4{margin:5px 0;font-size:14px}.timeline-card p,.catalog-card p{margin:5px 0 0;color:var(--muted);font-size:11px;line-height:1.45}
.lineage-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.lineage-grid>.card{padding:20px}.muted{color:var(--muted);font-size:12px;line-height:1.55}.tree{margin:18px 0 24px}.tree h4{font-size:13px;margin:0 0 8px}.tree-rail{display:flex;flex-wrap:wrap;gap:7px;align-items:center}.tree-node{padding:8px 10px;font-size:11px}.tree-arrow{color:#486274}.lineage-detail.empty{color:var(--muted);padding:40px 0}.lineage-path{display:flex;flex-wrap:wrap;gap:6px;align-items:center;margin:10px 0 18px}.lineage-block{margin:18px 0}.lineage-block h4{font-size:11px;color:var(--muted);text-transform:uppercase;letter-spacing:.08em}.lineage-chip{display:inline-block;padding:7px 9px;margin:3px;border-radius:9px;background:#0b1720;border:1px solid #29404d;font-size:11px;cursor:pointer}
.catalog-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:9px;padding:18px 20px 25px}.catalog-card .meta{font-size:10px;color:var(--accent);display:flex;justify-content:space-between;gap:8px}.catalog-card .badges{margin-top:10px}.empty-state{padding:50px;color:var(--muted);text-align:center}
.node-label{font-size:9px;fill:#dbe9ef;pointer-events:none;text-anchor:middle}.node circle{stroke:#071018;stroke-width:2.5}.node.selected circle{stroke:#fff;stroke-width:3}.link{stroke:#39515f;stroke-opacity:.42}.node{cursor:pointer}
@media(max-width:1050px){.hero{grid-template-columns:1fr}.controls{grid-template-columns:repeat(2,1fr)}.search-wrap{grid-column:span 2}.map-layout,.lineage-grid{grid-template-columns:1fr}.detail-panel{min-height:unset}.graph-card{min-height:600px}}
@media(max-width:650px){main{width:94vw;padding-top:20px}.topbar{padding:10px 3vw}.header-actions .link-button{display:none}.hero h2{font-size:42px}.stats{grid-template-columns:repeat(2,1fr)}.controls{grid-template-columns:1fr}.search-wrap{grid-column:auto}.tabs{padding-top:12px}.view-head{display:block}.legend{justify-content:flex-start;margin-top:12px}.graph-card{min-height:570px}#network{height:500px}.timeline-era{grid-template-columns:1fr}.catalog-grid{grid-template-columns:1fr}}

.source-list{display:grid;gap:7px}
.source-link{display:block;text-decoration:none;border:1px solid #243b49;background:#0b1720;border-radius:10px;padding:9px;color:var(--text)}
.source-link:hover{border-color:#527084}
.source-link strong{display:block;font-size:11px;line-height:1.35}
.source-link span{display:block;color:var(--muted);font-size:9px;line-height:1.35;margin-top:4px}
.reviewed{font-size:9px!important;color:var(--muted)!important;margin:8px 0 0!important}

.tree-selector-card{align-self:start}
.tree-choice-list{display:grid;gap:7px;margin-top:18px}
.tree-choice{width:100%;text-align:left;border:1px solid #223845;background:#0b1720;border-radius:12px;padding:11px 12px;color:var(--text);cursor:pointer}
.tree-choice:hover{border-color:#45657a}
.tree-choice.active{border-color:#5f8ca5;background:#132633;box-shadow:inset 3px 0 0 var(--accent)}
.tree-choice span{display:block;font-size:12px;font-weight:650;line-height:1.35}
.tree-choice small{display:block;margin-top:4px;color:var(--muted);font-size:9px}
.thought-tree-card{min-width:0;overflow:hidden}
.thought-tree-head{padding-bottom:8px}
.thought-tree-scroll{width:100%;overflow-x:auto;border:1px solid #1f3441;border-radius:14px;background:#08131c}
#thoughtTreeGraph{display:block;width:100%;min-width:900px;height:auto;min-height:430px}
.tree-grid line{stroke:#243845;stroke-width:1;stroke-dasharray:3 5}
.tree-grid text{fill:#718995;font-size:9px;text-transform:uppercase;letter-spacing:.04em}
.tree-year-axis line{stroke:#1d303c;stroke-width:1}
.tree-year-axis text{fill:#718995;font-size:9px;text-anchor:middle}
.tree-links path{fill:none;stroke:#587386;stroke-width:1.25;stroke-opacity:.62}
.tree-graph-node{cursor:pointer}
.tree-graph-node circle{stroke:#071018;stroke-width:2.5}
.tree-graph-node:hover circle{stroke:#bde9fa;stroke-width:3}
.tree-graph-node.selected circle{stroke:#fff;stroke-width:3.5}
.tree-graph-label{fill:#e4eef2;font-size:9px;text-anchor:middle;pointer-events:none}
.tree-graph-year{fill:#71909f;font-size:8px;text-anchor:middle;pointer-events:none}
.selected-lineage-panel{border-top:1px solid var(--line);margin-top:12px;padding-top:18px}
@media(max-width:1050px){.thought-tree-card{min-height:unset}.tree-selector-card{position:static}}

.formula-head{align-items:flex-start}
.formula-controls{display:grid;grid-template-columns:2fr 1fr 1.5fr;gap:12px;padding:18px 20px 4px}
.formula-controls label{display:block;font-size:10px;font-weight:750;color:var(--muted);margin:0 0 6px;text-transform:uppercase;letter-spacing:.06em}
.formula-controls input,.formula-controls select{width:100%;height:42px;border:1px solid #2c4151;background:#09141d;color:var(--text);border-radius:11px;padding:0 12px;outline:none}
.formula-controls input:focus,.formula-controls select:focus{border-color:var(--accent)}
.formula-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(330px,1fr));gap:10px;padding:18px 20px 26px}
.formula-card{min-width:0;border:1px solid #233845;border-radius:15px;background:#0a1620;padding:14px}
.formula-card h4{font-size:15px;line-height:1.3;margin:7px 0 9px}
.formula-card p{font-size:11px;line-height:1.55;color:#b6c8d1;margin:10px 0}
.formula-meta{display:flex;justify-content:space-between;gap:10px;color:var(--accent);font-size:9px;text-transform:uppercase;letter-spacing:.04em}
.formula-equation{min-height:76px;display:flex;align-items:center;justify-content:center;overflow-x:auto;background:#07121a;border:1px solid #1d3340;border-radius:11px;padding:12px 9px;margin:8px 0}
.formula-equation mjx-container{max-width:100%;overflow-x:auto;overflow-y:hidden;margin:0!important}
.formula-plain{font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:9px;color:#718b98;overflow-wrap:anywhere}
.formula-theories,.formula-sources{display:flex;gap:5px;flex-wrap:wrap;margin-top:9px}
.formula-theory{border:1px solid #315064;background:#102432;color:#b7d9e8;border-radius:999px;padding:4px 7px;font-size:9px;cursor:pointer}
.formula-theory:hover{border-color:#6f9db5;color:#eef9fd}
.formula-source{display:inline-block;text-decoration:none;border:1px solid #334333;background:#101d18;color:#b9d8c2;border-radius:999px;padding:4px 7px;font-size:8px}
.formula-source:hover{border-color:#56745e;color:#eaf5ed}
@media(max-width:850px){.formula-controls{grid-template-columns:1fr}.formula-grid{grid-template-columns:1fr}.formula-equation{min-height:64px}}

.formula-role-row{display:flex;flex-wrap:wrap;gap:7px;align-items:center;margin:7px 0 2px;color:var(--muted);font-size:10px}
.formula-role{display:inline-flex;border:1px solid #506a79;border-radius:999px;padding:4px 7px;color:#d7edf5;background:#10222d;text-transform:uppercase;letter-spacing:.05em;font-weight:700}
.formula-detail{margin:12px 0;display:grid;gap:7px}
.formula-detail>div{display:grid;grid-template-columns:82px 1fr;gap:8px;padding-top:7px;border-top:1px solid #1d313d}
.formula-detail dt{font-size:9px;color:var(--muted);text-transform:uppercase;letter-spacing:.06em}
.formula-detail dd{margin:0;font-size:10px;line-height:1.45;color:#b8cbd4}

.relation-main{display:grid;gap:3px;min-width:0}
.relation-main strong{font-size:11px;font-weight:650;overflow:hidden;text-overflow:ellipsis}
.relation-main em{font-size:8px;color:var(--muted);font-style:normal;text-transform:none;letter-spacing:.01em}

/* Dedicated details preserve the existing atlas and card styling. */
.theory-view{max-width:960px;margin:0 auto;scroll-margin-top:90px}
.theory-view>.link-button{margin-bottom:12px}
.theory-view .detail-panel{min-height:0}
.theory-view .detail-title{font-size:clamp(28px,4vw,40px)}
.detail-actions{display:flex;flex-wrap:wrap;gap:8px}
a.catalog-card,a.timeline-card,a.relation{display:block;text-decoration:none;color:inherit}
a.relation{display:flex}
a.catalog-card:focus-visible,a.timeline-card:focus-visible,a.relation:focus-visible{outline:2px solid var(--accent);outline-offset:3px}

/* Additive research and comparison surfaces; existing views keep their rules. */
.profile-citations{display:block;font-size:11px;line-height:1.6;overflow-wrap:anywhere;color:var(--muted)}
.profile-citations a,.comparison-table a{color:var(--accent)}
.comparison-panel{padding:24px;margin-bottom:18px;min-width:0}
.comparison-panel h3{margin:0 0 12px}
.comparison-selectors{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin:20px 0}
.comparison-selectors label{display:block;margin-bottom:7px;font-size:12px;color:var(--muted)}
.comparison-selectors select{width:100%;min-width:0;padding:10px;border:1px solid #315064;border-radius:10px;background:#07121a;color:inherit}
.comparison-scroll{max-width:100%;overflow-x:auto;margin-top:20px;border:1px solid #1d3340;border-radius:12px}
.comparison-scroll:focus-visible{outline:2px solid var(--accent)}
.comparison-table{border-collapse:collapse;width:100%;min-width:700px;text-align:left;font-size:13px;line-height:1.55}
.comparison-table caption{text-align:left;padding:14px;color:var(--muted)}
.comparison-table th,.comparison-table td{padding:16px;vertical-align:top;border-bottom:1px solid #1d3340;border-right:1px solid #1d3340;min-width:230px;overflow-wrap:anywhere}
.comparison-table th:first-child{min-width:150px;background:#0d1d27}
.comparison-table p{margin:0 0 8px}
.profile-collection{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px;margin-top:16px}
@media(max-width:850px){.comparison-selectors,.profile-collection{grid-template-columns:1fr}.comparison-panel{padding:16px}}

.learning-steps{padding-left:26px;line-height:1.65}.learning-steps li{padding:10px 0}.learning-steps a{color:var(--accent);font-weight:650}.learning-steps p{margin:4px 0;color:var(--muted)}.learning-path{overflow-wrap:anywhere}

[hidden]{display:none!important}.research-tools label{display:block;margin:14px 0 7px}.research-tools textarea{display:block;width:100%;max-width:100%;padding:12px;margin:8px 0;background:#07121a;color:var(--text);border:1px solid var(--line);border-radius:10px;font:inherit}.comparison-selectors input{width:100%;min-width:0;padding:10px;margin-bottom:8px;border:1px solid #315064;border-radius:10px;background:#07121a;color:var(--text)}.node:focus-visible circle,.tree-graph-node:focus-visible circle{stroke:#fff;stroke-width:3px}#workspaceContent a{color:var(--accent)}#workspaceContent input[type=file]{max-width:100%}.research-tools button{min-height:44px}

.learning-primer{border:1px solid var(--line);border-radius:12px;padding:16px;margin:20px 0;overflow-wrap:anywhere}
.primer-equation{font-size:1.2rem;font-family:Georgia,serif}
.relation-evidence{padding:0 12px 12px;font-size:.85rem;overflow-wrap:anywhere}
.relation-evidence summary{cursor:pointer;padding:8px 0}

#workspaceContent .detail-actions label{width:100%;min-width:0;max-width:100%}
#workspaceContent input[type=file]{display:block;width:100%;min-width:0;margin-top:8px}

.learning-progress{margin:16px 0 22px;min-width:0;overflow-wrap:anywhere}
.learning-progress progress{display:block;width:100%;height:8px;accent-color:var(--accent)}
.learning-progress .link-button{min-height:44px}
.learning-step-status{display:inline-block;margin-left:8px;font-size:.75rem;color:var(--muted)}
.learning-step-status.is-read{color:var(--accent)}
.workspace-path{border-bottom:1px solid var(--line);padding:12px 0;min-width:0;overflow-wrap:anywhere}
.workspace-path h5{font-size:1rem;margin:0}
.workspace-path .learning-progress{margin-bottom:8px}

.workspace-collections{min-width:0;overflow-wrap:anywhere}
.workspace-collections label{display:block;margin:14px 0 7px}
#workspaceSearch{display:block;width:100%;min-width:0;max-width:100%;padding:12px;border:1px solid var(--line);border-radius:10px;background:#07121a;color:var(--text);font:inherit}
#workspaceSearch:focus-visible{outline:2px solid var(--accent);outline-offset:2px}

.evidence-controls{padding:16px;margin:12px 0}.evidence-controls label{display:block;margin-bottom:8px}.evidence-controls select{max-width:100%;padding:10px;background:#07121a;color:var(--text);border:1px solid var(--line);border-radius:10px}.lineage-chip{display:inline-block}#coverageContent .comparison-table{min-width:620px}


/* Bright scientific editorial theme — 2026-09-27.
   Visual-only overrides: preserve the existing layout, routes and interaction model. */
:root{
  --bg:#f5f8fa;
  --surface:#ffffff;
  --surface2:#eef6f8;
  --line:#d8e3e8;
  --text:#17313f;
  --muted:#607684;
  --accent:#0e8fa3;
  --accent2:#7569d8;
  --good:#217a52;
  --warn:#9a6510;
  --danger:#b83a47;
  --shadow:0 14px 38px rgba(43,78,97,.09);
  --shadow-soft:0 6px 20px rgba(43,78,97,.07);
  --focus:0 0 0 3px rgba(14,143,163,.16)
}
html{
  color-scheme:light;
  background:var(--bg);
  color:var(--text);
}
body{
  background:
    radial-gradient(circle at 10% -8%,rgba(14,143,163,.11),transparent 32rem),
    radial-gradient(circle at 90% 2%,rgba(117,105,216,.09),transparent 28rem),
    linear-gradient(180deg,#fbfdfe 0,#f5f8fa 24rem,#f5f8fa 100%);
}
::selection{background:rgba(14,143,163,.18);color:#0e2937}
a{color:#087d91;text-underline-offset:3px}
.topbar{
  background:rgba(255,255,255,.91);
  border-bottom:1px solid rgba(113,141,157,.18);
  box-shadow:0 5px 24px rgba(52,79,94,.06);
  backdrop-filter:blur(20px) saturate(1.15);
}
.brand-mark{
  color:#fff;
  background:linear-gradient(135deg,#0e9ab0 0%,#5c75d6 55%,#8a6ed4 100%);
  box-shadow:0 10px 26px rgba(48,119,149,.2)
}
.brand h1{color:#16303e;font-weight:780}
.brand p{color:#67808d}
.header-actions .ghost{background:rgba(255,255,255,.82)}
main{width:min(1540px,94vw);padding-top:28px}
.hero{
  align-items:center;
  padding:38px 38px 34px;
  margin:4px 0 20px;
  border:1px solid #dce8ed;
  border-radius:28px;
  background:
    radial-gradient(circle at 82% 5%,rgba(117,105,216,.12),transparent 21rem),
    linear-gradient(135deg,#ecf9fb 0%,#f7f7ff 52%,#fff9f0 100%);
  box-shadow:0 18px 48px rgba(62,91,107,.08)
}
.hero .eyebrow{color:#087f93}
.hero h2{color:#142d3b;font-weight:760;letter-spacing:-.05em}
.hero-copy{color:#526d7a;max-width:800px}
.stats{gap:11px}
.stat{
  background:rgba(255,255,255,.83);
  border:1px solid #dbe7ec;
  box-shadow:0 8px 24px rgba(53,84,100,.07);
  backdrop-filter:blur(8px)
}
.stat strong{color:#17313f;font-weight:760}
.stat span{color:#617987}
.card{
  background:rgba(255,255,255,.97);
  border-color:#d8e3e8;
  box-shadow:var(--shadow)
}
.controls{padding:16px}
.controls label,.formula-controls label{color:#607684}
.controls input[type=search],.controls select,
.formula-controls input,.formula-controls select,
.comparison-selectors select,.comparison-selectors input,
.research-tools textarea,#workspaceSearch,.evidence-controls select{
  background:#fff;
  color:#17313f;
  border-color:#cbdbe2;
  box-shadow:inset 0 1px 0 rgba(34,68,85,.02)
}
.controls input::placeholder,.formula-controls input::placeholder,
.comparison-selectors input::placeholder,#workspaceSearch::placeholder{color:#8ca0aa}
